const names = ['Cover','Getting Started','Foundations','— Components —','Components','— Utilities —','Utilities'];
const createdNodeIds = [], mutatedNodeIds = [], pages = {};
const current = await figma.getNodeByIdAsync('0:1');
if (!current || current.type !== 'PAGE' || current.name !== 'Page 1' || current.children.length !== 0) throw new Error('Page initiale différente du registre ; contrôler avant création.');
current.name = 'Cover';
mutatedNodeIds.push(current.id);
pages.Cover = current.id;
for (const name of names.slice(1)) {
 const existing = figma.root.children.find(p => p.name === name);
 if (existing) {pages[name] = existing.id; continue;}
 const page = figma.createPage();
 page.name = name;
 pages[name] = page.id;
 createdNodeIds.push(page.id);
}
return {step:'P2.a',pages,createdNodeIds,mutatedNodeIds};
